const item = $input.item.json;
const config = $input.item.json;
// config comes from the previous Split In Batches/loop context
// We need to get the config from the Configure URLs node
const urls = [
  { name: 'Main Site', url: 'https://emil.aiadoption.cz', expectedStatus: 200, maxResponseTimeMs: 5000 },
  { name: 'API Health', url: 'https://emil.aiadoption.cz/api/health', expectedStatus: 200, maxResponseTimeMs: 3000 },
  { name: 'RSS Feed', url: 'https://emil.aiadoption.cz/blog/index.xml', expectedStatus: 200, maxResponseTimeMs: 5000 }
];

return [{
  json: {
    allResults: items.map((item, index) => {
      const cfg = urls[index];
      const status = item.json.status;
      const responseTime = item.json.responseTimeMs || 0;
      const isDown = status !== cfg.expectedStatus || responseTime > cfg.maxResponseTimeMs;
      const isSlow = !isDown && responseTime > cfg.maxResponseTimeMs * 0.8;
      let severity = '🟢';
      if (isDown) severity = '🔴';
      else if (isSlow) severity = '🟡';
      return {
        name: cfg.name,
        url: cfg.url,
        status: status,
        responseTimeMs: responseTime,
        expectedStatus: cfg.expectedStatus,
        maxResponseTimeMs: cfg.maxResponseTimeMs,
        isDown: isDown,
        isSlow: isSlow,
        severity: severity
      };
    })
  }
}];

const results = $input.item.json.allResults;
const hasAlert = results.some(r => r.isDown || r.isSlow);

let message;
if (hasAlert) {
  const lines = results.map(r => {
    let line = `${r.severity} ${r.name}: ${r.status} (${r.responseTimeMs}ms`;
    if (r.isDown) line += `, expected ${r.expectedStatus}`;
    if (r.isSlow) line += `, slow (limit ${r.maxResponseTimeMs}ms)`;
    return line;
  });
  message = `⚠️ URL Monitor Alert\n\n${lines.join('\n')}`;
} else {
  message = `✅ All URLs healthy\n\n${results.map(r => `${r.severity} ${r.name}: ${r.status} (${r.responseTimeMs}ms)`).join('\n')}`;
}

return [{ json: { message, hasAlert } }];
